    "sol": "Устя — 2, Сара — 5, Варвара — 10. Пусть Устя в r промежутках от Клары, тогда до Варвары ей 4r. Три точки на прямой стоят либо так, что Устя между Кларой и Варварой (между ними r + 4r = 5r), либо так, что Устя сбоку (4r − r = 3r). Значит, расстояние Клара — Варвара равно 3r или 5r; при r = 1 это 3 или 5, при r = 2 это 6 (вариант 10 длиннее провода), при r = 3 получается 9, но от 4-го места на 9 промежутков не уйти. Итак, для Усти возможны 3, 5 и 6. Для Сары, если до Клары q промежутков, между Кларой и Варварой будет 4q или 6q: при q = 1 это 4 или 6, при q = 2 это 8 (вариант 12 длиннее). Для Сары возможны 4, 6 и 8. Общее только 6, значит, Варвара в шести промежутках от Клары: 4 + 6 = 10 (вариант 4 − 6 не подходит). Для Усти 3r = 6, то есть r = 2: это 2-е или 6-е место, но с 6-го места до Варвары 4 промежутка вместо 4r = 8, поэтому Устя на 2-м месте. Для Сары 6q = 6, то есть q = 1: это 3-е или 5-е место, но с 3-го места до Варвары 7 промежутков вместо 5, поэтому Сара на 5-м месте. Проверка: Устя — до Клары 2, до Варвары 8, и 8 : 2 = 4; Сара — до Клары 1, до Варвары 5, и 5 : 1 = 5.",
