    "sol": "Часть А: 999. Первая цифра 2, поэтому нужно, чтобы произведение четырёх оставшихся цифр делилось на 4. Всего чисел 6⁴ = 1296. Не делятся на 4 только те, у которых все четыре цифры нечётные (3⁴ = 81), либо ровно одна цифра чётная и не кратная 4 (цифра 2 или 6 — 2 способа, её место — 4 способа, остальные три места — любые из трёх нечётных: 2 · 4 · 3³ = 216). Неподходящих 81 + 216 = 297, подходящих 1296 − 297 = 999; полный перебор всех 1296 наборов это подтверждает. Часть Б: подходят 2025 × 2025, 2025 × 2027, 2026 × 2026 и 2027 × 2027, то есть прямоугольники с обеими сторонами одной чётности. Если стороны разной чётности, то квадратиков чётное число, у каждого ровно одна красная сторона, но сторона нечётной длины даёт нечётное число наружных красных сторон, а внутренние красные стороны склеиваются парами, то есть их чётное число, — противоречие. Для одной чётности прямоугольник собирается: сначала цепочка квадратиков нужной длины, затем такие полоски склеиваются между собой.",
    "trap": "В части А перечислять подходящие числа по одному и утонуть: подходящих 999 и почти все они «обычные». В части Б поверить, что размеров должно быть ровно четыре из-за чётности, и не проверить, что 2026 × 2026 (обе стороны чётные) тоже годится, а 2026 × 2027 и 2025 × 2026 — нет.",
