    "темаКоротко": "Геометрия · прямоугольный треугольник, окружности и теорема Пифагора",
    "points": 7,
    "theme": "9 класс · Геометрия · прямоугольный треугольник, окружности и теорема Пифагора · сложность 4",
    "q": "Найди длину отрезка DE.",
    "материал": "Створка декорации — прямоугольный треугольник ABC с прямым углом при вершине C. В ней прорезают два круглых окна: одно с центром в A, проходящее через C, второе с центром в B, тоже проходящее через C. Дуги окон пересекают гипотенузу AB в точках E и D соответственно. Известно, что AD = 16, а BE = 50.\n\nПравило: Окружность с центром A проходит через C, поэтому AC = AE = AD + DE; окружность с центром B проходит через C, поэтому BC = BD = BE + ED; точки на гипотенузе идут в порядке A, D, E, B, а AB = AD + DE + EB. Теорема Пифагора даёт уравнение, из которого x² = 2 · AD · BE",
