    "hint": "Сначала разберись с порядком точек на гипотенузе: сумма катетов больше гипотенузы, поэтому AD + EB < AB и точки D и E лежат внутри, D ближе к A.",
    "hints": [
     "Сначала разберись с порядком точек на гипотенузе: сумма катетов больше гипотенузы, поэтому AD + EB < AB и точки D и E лежат внутри, D ближе к A.",
     "Обозначь DE = x. Тогда AC = AE = 16 + x, BC = BD = 50 + x, а вся гипотенуза AB = 66 + x.",
     "Запиши теорему Пифагора: (16 + x)² + (50 + x)² = (66 + x)². Два x² слева и один справа, а слагаемые с x сокращаются — останется короткое уравнение."
    ],
    "sol": "Обозначим DE = x. Так как AC + BC > AB, точки D и E лежат внутри гипотенузы, и порядок такой: A, D, E, B. Окружность с центром A проходит через C, значит AC = AE = AD + DE = 16 + x. Окружность с центром B проходит через C, значит BC = BD = BE + ED = 50 + x. Гипотенуза AB = AD + DE + EB = 16 + x + 50 = 66 + x. Теорема Пифагора: (16 + x)² + (50 + x)² = (66 + x)², то есть 256 + 32x + x² + 2500 + 100x + x² = 4356 + 132x + x². Слагаемые 132x сокращаются, остаётся x² = 4356 − 256 − 2500 = 1600, откуда x = 40. Проверка: катеты 56 и 90, гипотенуза 106, и 56² + 90² = 3136 + 8100 = 11236 = 106².",
